chrome.action.onClicked.addListener((tab) => {
  chrome.scripting.executeScript({
    target: { tabId: tab.id },
    function: getPositions
  }).then((results) => {
    if (results && results.length > 0 && results[0].result) {
      const positions = results[0].result;
      createPositionWindow(positions);
    }
  });
});

function getPositions() {
  const positionElements = document.querySelectorAll('.by-table-cell-group');
  const positions = [];
  positionElements.forEach((element, index) => {
    if (index !== 0) { // Пропускаем первую позицию
      positions.push(element.innerText);
    }
  });
  return positions;
}

// Слушаем сообщения от popup.js
chrome.runtime.onMessage.addListener((request, sender, sendResponse) => {
  if (request.action === 'updatePositions') {
    chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
      chrome.scripting.executeScript({
        target: { tabId: tabs[0].id },
        function: getPositions
      }).then((results) => {
        if (results && results.length > 0 && results[0].result) {
          const positions = results[0].result;
          sendResponse(positions);
        } else {
          sendResponse([]);
        }
      });
    });
    return true; // Указываем, что ответ будет отправлен асинхронно
  }
});

