let isUpdating = true; // Переменная для обновления данных

chrome.runtime.onMessage.addListener((message, sender, sendResponse) => {
  if (message.action === 'updateFlag') {
    isUpdating = message.isUpdating;
    console.log('isUpdating обновлено:', isUpdating);
  }
});

function updateData() {

  chrome.tabs.query({ active: true, currentWindow: true }, (tabs) => {
    if (!isUpdating) return;

    if (tabs.length === 0) return; // Нет активной вкладки

    chrome.scripting.executeScript({
      target: { tabId: tabs[0].id },
      func: () => {
        document.querySelectorAll('.by-table-row').forEach((row) => {
          const cells = row.querySelectorAll('.by-table-cell');
          // Проверяем, существуют ли необходимые ячейки
          if (cells.length > 11) { // Убедитесь, что ячеек достаточно
            const orderPriceCell = cells[8];
            const directionCell = cells[5];
            const proposalCell = cells[11];
            const demandCell = cells[7];

            if (directionCell && directionCell.innerText === 'Купить' && proposalCell) {
              orderPriceCell.innerText = proposalCell.innerText; // Ставим "Цену предложения"
            } else if (directionCell && directionCell.innerText === 'Продать' && demandCell) {
              orderPriceCell.innerText = demandCell.innerText; // Ставим "Цену спроса"
            }
          } else {
            console.warn('Строка таблицы содержит меньше ячеек, чем ожидается:', row);
          }
        });
      },
    });
  });
}

// Запускаем обновление данных каждую секунду
setInterval(updateData, 500);

