import sys
import json
import re
import math
from PyQt5.QtWidgets import (QApplication, QWidget, QVBoxLayout, QLabel, QPushButton,
                             QHBoxLayout, QScrollArea, QGroupBox, QGridLayout, QFrame,
                             QMessageBox, QDoubleSpinBox)
from PyQt5.QtGui import QFont, QColor
from PyQt5.QtCore import (Qt, QTimer, QThread, pyqtSignal)
import pandas as pd
import key
from pybit.unified_trading import HTTP
import time
import datetime
import pytz


# Initialize Bybit API session
session = HTTP(
    api_key=key.APIK,
    api_secret=key.APISK,
)


# Function to extract expiry date from contract name
def extract_expiry_date(contract_name):
    pattern = r'BTC-(\d+[A-Z]+\d+)'
    match = re.search(pattern, contract_name)
    if match:
        return match.group(1)
    return None


# Function to extract strike price from option contract name
def extract_strike_price(contract_name):
    pattern = r'BTC-\d+[A-Z]+\d+-(\d+)'
    match = re.search(pattern, contract_name)
    if match:
        return float(match.group(1))
    return None


