$s3Bucket = "s3://magicxpi-audit-logs/HIS_TO_FFR/"
$cutoffDate = (Get-Date).AddDays(-7)

# Get all top-level folders in Audit_Log
Get-ChildItem -Path $logsPath -Directory | ForEach-Object {
    # For each top-level folder, get the date-wise subfolders
    Get-ChildItem -Path $_.FullName -Directory | ForEach-Object {
        # Move folders older than 7 days to S3
        Get-ChildItem -Path $_.FullName -Directory | Where-Object { $_.LastWriteTime -lt $cutoffDate } | ForEach-Object {
            aws s3 mv $_.FullName $s3Bucket --recursive
        }
    }
}

