(function() {
    // Create an array to hold the video IDs
    let videoLinks = [];

    // Query all the link elements pointing to videos in the playlist
    const videoElements = document.querySelectorAll('a[href*="watch"]');

    // Iterate through the videos and extract their IDs
    videoElements.forEach(videoElement => {
        // Parse out the URL parameters
        const url = new URL(videoElement.href);
        const videoId = url.searchParams.get('v');

        // Ensure the video ID is not null and unique before adding
        if (videoId && !videoLinks.includes(videoId)) {
            videoLinks.push(videoId);
        }
    });

    // Format the output as requested
    const formattedOutput = videoLinks.map(id => https://youtu.be/${id});
    console.log(‘"’ + formattedOutput.join('", "') + '"');
})();

