fn query_swap_chain_support(
    physical_device: &vk::PhysicalDevice,
    window_surface: &vk::SurfaceKHR,
    surface_loader: &ash::khr::surface::Instance,
) -> Result<SwapChainSupportDetails, anyhow::Error> {
    let surface_capabilities = unsafe {
        surface_loader.get_physical_device_surface_capabilities(*physical_device, *window_surface)
    };

    let surface_capabilities = match surface_capabilities {
        Ok(capabilities) => capabilities,
        Err(result) => {
            return Err(anyhow::anyhow!(
                "Failed to get surface capabilities {}",
                result
            ))
        }
    };

    let surface_formats = unsafe {
        surface_loader.get_physical_device_surface_formats(*physical_device, *window_surface)
    };

    let surface_formats = match surface_formats {
        Ok(formats) => formats,
        Err(result) => return Err(anyhow::anyhow!("Failed to get surface formats {}", result)),
    };

    let presentation_modes = unsafe {
        surface_loader.get_physical_device_surface_present_modes(*physical_device, *window_surface)
    };

    let presentation_modes = match presentation_modes {
        Ok(modes) => modes,
        Err(result) => {
            return Err(anyhow::anyhow!(
                "Failed to get presentation modes {}",
                result
            ))
        }
    };

    Ok(SwapChainSupportDetails {
        capabilities: surface_capabilities,
        formats: surface_formats,
        present_modes: presentation_modes,
    })
}

