{
name: "Boss Summon - Shadow Minions",
description: "Boss summons 4 shadow minions that follow and attack the player.",
func: () => {
if(!boss) {
log("No active boss to summon minions.");
return;
}


  const minions = [];
  for(let i=0; i<4; i++) {
    const minion = document.createElement('div');
    minion.classList.add('enemy');
    minion.style.position = 'absolute';
    minion.style.backgroundColor = 'rgba(20, 20, 20, 0.8)';
    minion.style.left = (parseInt(boss.style.left) + i * 45) + 'px';
    minion.style.bottom = (parseInt(boss.style.bottom) + 10) + 'px';
    minion.style.width = '30px';
    minion.style.height = '30px';
    minion.style.borderRadius = '50%';
    gameWorld.appendChild(minion);
    enemies.push(minion);
    minions.push(minion);
  }

  // Minion follow and attack
  const interval = setInterval(() => {
    minions.forEach((minion, idx) => {
      if(!minion.parentElement) {
        minions.splice(idx, 1);
        if(minions.length === 0) clearInterval(interval);
        return;
      }
      let mx = parseFloat(minion.style.left);
      let my = parseFloat(minion.style.bottom);
      let px = playerPositionX;
      let py = playerPositionY;

      const dx = px - mx;
      const dy = py - my;
      const dist = Math.hypot(dx, dy);

      if(dist > 5) {
        minion.style.left = (mx + (dx / dist) * 3) + 'px';
        minion.style.bottom = (my + (dy / dist) * 3) + 'px';
      }

      if(checkCollision(minion, player)) {
        reduceLives();
        createBurst(mx, my);
        minion.remove();
        enemies.splice(enemies.indexOf(minion), 1);
        minions.splice(idx, 1);
      }
    });
  }, 50);

  log("Boss summoned Shadow Minions!");
}


