import os
import gradio as gr
from context_loader import ContextLoader
from models.gpt4o import ModelClient


class NeuroRavenApp:
    def __init__(self):
        self.system_prompt = None
        self.current_theme = None
        self.client = ModelClient()
        self.context_loader = ContextLoader()
        self.conversation_themes = self.get_conversation_themes()
        if "Без контекста" not in self.conversation_themes:
            self.conversation_themes.append("Без контекста")

    @staticmethod
    def get_conversation_themes(docs_path='docs'):
        # Получаем список всех директорий в указанном пути
        return [name for name in os.listdir(docs_path) if os.path.isdir(os.path.join(docs_path, name))]

    def handle_query(self, message, history, audio, context_theme):
        if audio:

        if context_theme != self.current_theme:
            context = self.context_loader.load_txt_files(context_theme)
            if context:
                self.system_prompt = f"Отвечай на вопросы беря информацию из контекста: 
{context}"
            else:
                self.system_prompt = "You are a helpful assistant."

            self.current_theme = context_theme

        response = self.client.get_response(
            message=message,
            history=history,
            sys_prompt=self.system_prompt
        )
        return response

    def launch_app(self):
        gr.ChatInterface(
            self.handle_query,
            chatbot=gr.Chatbot(height=500),
            retry_btn=None,
            clear_btn="Clear",
            theme="soft",
            title="NeuroRaven",
            css="footer{display:none !important}",
            additional_inputs=[
                gr.Microphone(sources=["microphone"], type="numpy"),
                gr.Dropdown(self.conversation_themes, label="Выбери тему контекста", value="Без контекста"),
            ]
        ).launch()


if __name__ == "__main__":
    app = NeuroRavenApp()
    app.laun

using iRIS.InsuranceCore.OSS.Code.Dto.Deserialization;
using iRIS.InsuranceCore.OSS.Code.Dto.OssSearchPolicy;
using System.IO;
using System.Xml.Linq;
using System.Xml.Serialization;

namespace iRIS.InsuranceCore.OSS.Code
{
    public static class OssUniDeserializer
    {
        /// <summary>
        /// Десериализация xml в OssUniDeserializationDto.
        /// </summary>
        /// <param name="xml">XML.</param>
        /// <returns>Десериализованная модель.</returns>
        public static OssUniDeserializationDto DeserializeToPolicy(string xml)
        {
            if (!xml.StartsWith("<ObjectList>"))
            {
                xml = $"<ObjectList>{xml}</ObjectList>";
            }

            var policy = XElement.Parse(xml).Element("policy");

            var xmlSerializer = new XmlSerializer(
                type: typeof(OssUniPolicyDeserializationDto),
                root: new XmlRootAttribute() { ElementName = "policy" });

            var uniDeserializationDto = new OssUniDeserializationDto();

            using (var reader = new StringReader(policy.ToString()))
            {
                uniDeserializationDto.Policy = (OssUniPolicyDeserializationDto)xmlSerializer.Deserialize(reader);
            }

            return uniDeserializationDto;
        }

        /// <summary>
        /// Десериализация xml в OssUniPolicyProlCoeffDto.
        /// </summary>
        /// <param name="xml">XML.</param>
        /// <returns>Десериализованная модель.</returns>
        public static OssUniProlCoeffDeserializationDto DeserializeToPolicyProlCoeff(string xml)
        {
            var xmlSerializer = new XmlSerializer(
                type: typeof(OssUniProlCoeffDeserializationDto),
                root: new XmlRootAttribute() { ElementName = "policy-prolcoeff" });

            using (var reader = new StringReader(xml))
            {
                return (OssUniProlCoeffDeserializationDto)xmlSerializer.Deserialize(reader);
            }
        }

import io
from flask import Flask, render_template, request, redirect, url_for, abort, send_file
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime, timedelta
import requests

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///database.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)


class Bot(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(50), nullable=False)
    url = db.Column(db.String(200), nullable=False)
    last_heartbeat = db.Column(db.DateTime, default=datetime.utcnow)


class Message(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    bot_id = db.Column(db.Integer, db.ForeignKey('bot.id', ondelete='CASCADE'), nullable=False)
    content_data = db.Column(db.LargeBinary)
    content_mime_type = db.Column(db.String(50))
    response_data = db.Column(db.LargeBinary)
    response_mime_type = db.Column(db.String(50))
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)


@app.route('/')
def index():
    inactive_time = datetime.utcnow() - timedelta(seconds=60)
    Bot.query.filter(Bot.last_heartbeat < inactive_time).delete()
    db.session.commit()
    bots = Bot.query.all()
    return render_template('index.html', bots=bots)


@app.route('/message/<int:message_id>/content')
def get_message_content(message_id):
    message = Message.query.get_or_404(message_id)
    if not message.content_data:
        abort(404)
    return send_file(
        io.BytesIO(message.content_data),
        mimetype=message.content_mime_type
    )


@app.route('/message/<int:message_id>/response')
def get_message_response(message_id):
    message = Message.query.get_or_404(message_id)
    if not message.response_data:
        abort(404)
    return send_file(
        io.BytesIO(message.response_data),
        mimetype=message.response_mime_type
    )


