/**
* Implementing robust audit and logging mechanisms can provide valuable insights into user actions, data changes, and 
* potential security issues. 
*
* Use behaviors when you want to automatically tie logging to model lifecycle events without explicitly 
* writing logging code each time. To apply this behavior to a model, you would add it to the model's 
* behaviors:
*
* 	public function behaviors()
* 	{
* 		return [
* 			AuditLogBehavior::class,
* 		];
* 	}
*/
class AuditLogBehavior extends Behavior
{
	public function events()
	{
		return [
			ActiveRecord::EVENT_AFTER_INSERT => 'logInsert',
			ActiveRecord::EVENT_AFTER_UPDATE => 'logUpdate',
			ActiveRecord::EVENT_AFTER_DELETE => 'logDelete',
		];
	}

	public function logInsert($event)
	{
		\Yii::info('Record inserted: ' . json_encode($event->sender->attributes), 'audit');
	}

	public function logUpdate($event)
	{
		\Yii::info('Record updated: ' . json_encode($event->sender->attributes), 'audit');
	}

	public function logDelete($event)
	{
		\Yii::info('Record deleted: ID ' . $event->sender->getPrimaryKey(), 'audit');
	}
}


