        throw new \yii\web\NotFoundHttpException('User not found.');
    }

    $model = new EmailForm($user);

    if ($model->load(Yii::$app->request->post()) && $model->validate() && $model->changeEmail()) {
        Yii::$app->session->setFlash('success', 'Email has been updated.');
        return $this->redirect(['profile']);
    }

    // Re-fetch the user to ensure state consistency (if you suspect state changes)
    $user = $this->findModel($id);

    return $this->render('email', ['model' => $model, 'user' => $user]);
}

