class RoleHelper
{
	public static function isGuest(): bool
	{
		$guest = \Yii::$app->user->isGuest ? true : false;

		return (bool) $guest;
	}

	public static function userIdentity(): IdentityInterface|null
	{
		if (self::isGuest())
		{
			return null;
		}

		$identity = \Yii::$app->user->identity;
		if ($identity instanceof IdentityInterface)
		{
			return $identity;
		}

		// Defensive fallback: If identity is not instance, treat as guest
		return null;
	}

	public static function isAdmin(): bool
	{
		if (self::isGuest())
		{
			return false;
		}

		$identity = self::userIdentity();
		if ($identity === null || empty($identity->email))
		{
			return false;
		}

		$userId = $identity->id;
		if (self::hasRole($userId) != 'appAdmin')
		{
			return false;
		}

		$ip = self::userIp();
		$email = $identity->email;

		// Use both role and IP/email match for admin
		return \Yii::$app->authManager->checkAccess(self::userId(), 'appAdmin') 
			&& RBAMHelper::isAdmin($email, $ip);
	}

	public static function hasRole($userId): string
	{
		$authManager = \Yii::$app->authManager;
