export function setYupErrors
(
	validationError: any,
	setFormValidationErrors: Dispatch<SetStateAction<ApiErrorDetail>>
): void 
{
	if (validationError?.inner && Array.isArray(validationError.inner))
	{
		const yupErrors: ApiErrorDetail = {};

		validationError.inner.forEach((errorItem: any) =>
		{
			if (errorItem.path && !(errorItem.path in yupErrors))
			{
				yupErrors[errorItem.path] = errorItem.message;
			}
		});

		logger.log('Yup validation errors:', yupErrors);

		setFormValidationErrors(yupErrors);
	}
	else
	{
		logger.warn('Yup ValidationError missing inner array or invalid format:', validationError);

		setFormValidationErrors({});
	}
}

