	/**
	* Authenticates a user based on JWT stored in the 'access_token' cookie.
	* @param \yii\web\User $user The user component that manages authentication state and identity.
	* @param \yii\web\Request $request The current request object.
	* @param \yii\web\Response $response The current response object.
