	/**
	* Converts a duration string (e.g., '+30 minutes', '+1 hour') into an integer.
	* @param string $durationString The duration string to convert.
	* @return int The equivalent duration in seconds. Defaults to 1800 seconds if the string is invalid.
	*/
	public static function convertDurationToSeconds(string $durationString): int
	{
		// We can directly use strtotime to get the seconds; if it fails, fallback to default (30 minutes).
		$timestamp = strtotime($durationString);

		if ($timestamp === false)
		{
			$errorId = uniqid('account_deletion_error_', true);
			LogHelper::error('Invalid duration string: ' . $durationString . '. Defaulting to 30 minutes. Error ID:' . $errorId, [
				'method' => __METHOD__,
			]);

			return 1800;// Default to 30 minutes in seconds
		}

		$now = time();

		return $timestamp - $now;
	}
}
