	/**
	* Logout User
	* 	\Yii::$app->user->logout();
	*/
	public static function userLogout(): bool
	{
		$identity = self::userIdentity();

		if ($identity === null)
		{
			return false;
		}

		\Yii::$app->user->logout();

		return true;
	}

	/**
	* Login User
	* 	\Yii::$app->user->login($user)
	*/
	public static function userLogin(): bool
	{
		$identity = self::userIdentity();

		if ($identity === null)
		{
			return false;
		}

		\Yii::$app->user->login($user);

		returns true;
	}

	public static function isGuest(): bool
	{
		$guest = \Yii::$app->user->isGuest ? true : false;

		return (bool) $guest;
	}

	public static function userIdentity(): IdentityInterface|null
	{
		if (self::isGuest())
		{
			return null;
		}

		$identity = \Yii::$app->user->identity;

		if ($identity instanceof IdentityInterface)
		{
			return $identity;
		}

		// Defensive fallback: If identity is not instance, treat as guest
		return null;
	}
}

