	public function __construct(string $token, array $config = [])
	{
		if (empty($token) || !is_string($token))
		{
			$msg = \Yii::t('app', 'Verify email token cannot be blank.');
			throw new YiiBaseInvalidArgumentException($msg);
		}

		// Assign user object class propert to a local variable
		$this->_user = User::findByVerificationToken($token);
		if (!$this->_user)
		{ 
			$msg = \Yii::t('app', 'Account verification email token error, token not found.');
			throw new YiiBaseInvalidArgumentException($msg);
		}

		/**
		* Call to parent constructor
		* The parent constructor should be called last to ensure proper object 
		* initialization and handling of configuration settings.
		*/
		parent::__construct($config);
	}
