/**
* Interface SessionInterface
* Defines the contract for session management classes.
* Any session management implementation should adhere to this interface,
* providing methods to interact with session data.
*/
interface SessionInterface
{
	/**
	* Get the current session ID.
	* @return string The session ID.
	*/
	public function getId(): string;

	/**
	* Set a value in the session.
	* @param string $key The key to store the value under.
	* @param mixed $value The value to store.
	*/
	public function set(string $key, $value): void;

	/**
	* Get a value from the session.
	* @param string $key The key to retrieve the value from.
	* @return mixed The value associated with the given key or null if not found.
	*/
	public function get(string $key);

	/**
	* Check if a key exists in the session.
	* @param string $key The key to check.
	* @return bool True if the key exists, false otherwise.
	*/
	public function has(string $key): bool;

	/**
	* Remove a value from the session.
	* @param string $key The key to remove.
	*/
	public function remove(string $key): void;

	/**
	* Destroy the current session.
	*/
	public function destroy(): void;

	/**
	* Checks if the session is active
	* @return bool if session is open.
	*/
	public function isActive(): bool;
}

