namespace app\components\services;

use \Throwable;

use Yii;
use yii\db\Exception as YiiDbException;

use app\components\SessionManager;
use app\components\interfaces\SessionInterface;
use app\models\SessionUser;
use app\helpers\ExceptionLogger;
use app\helpers\LogHelper;
use app\helpers\RoleHelper;

class SessionUserService
{
	private bool $_debugMode = true;

	/**
	* Session Manager Interface
	* @see app\components\interfaces\SessionInterface.php
	* @var SessionInterface
	*/
	private SessionInterface $_sessionManager;

	/**
	* Cache the SessionUser model during request lifecycle.
	* @var SessionUser|null
	*/
	private ?SessionUser $_cachedSessionUser = null;

	// @var Cache tokens per session ID
	private array $_cachedSessionTokens = [];

	public function __construct(?SessionInterface $sessionManager = null)
	{
		$this->_sessionManager = $sessionManager ?? new SessionManager();
	}

	/**
	* Has Session
	* @return bool
	*
	* Checks whether there is valid session data in the Yii session store
	* for the current user's session token.
	*/
	public function hasSession(): bool
	{
		$sessionId = $this->_sessionManager->getId();
		if (empty($sessionId))
		{
			return false;
		}

		$sessionToken = $this->getSessionToken($sessionId);
		if ($sessionToken === null)
		{
			return false;
		}

		$key = SessionUser::SESSION_USER_KEY_PREFIX . substr($sessionToken, 0, 16);

		return $this->_sessionManager->has($key);
	}

	/**
	* Write or update the session data.
	* @param array $data Associative array with optional 'extra_data' keys.
	* @param bool $allowCriticalFieldUpdate Whether to allow updating token, IP, agent fields on existing record.
	* @return bool True on success, false on failure.
	* Validates data, generates tokens if missing, sets session data both in Yii session storage (via SessionInterface)
	* and persists in DB.
	*
	* Example usage:
