	const TYPE_CATALOG = 4;

	public function rules(): array
	{
		return [
			['type', 'required'],
			['type', 'integer'],
			['type', 'default', 'value' => self::TYPE_ARTICLE],
			['type', 'in', 'range' => [
				self::TYPE_ARTICLE,
				self::TYPE_EXHIBITION,
				self::TYPE_ARTIST,
				self::TYPE_CATALOG,
			]],
		];
	}

	/**
	* Get type labels to use in dropdowns, etc.
	*/
	public static function getTypeList(): array
	{
		return [
			self::TYPE_ARTICLE => \Yii::t('app', 'Article'),
			self::TYPE_EXHIBITION => \Yii::t('app', 'Exhibition'),
			self::TYPE_ARTIST => \Yii::t('app', 'Artist'),
			self::TYPE_CATALOG => \Yii::t('app', 'Catalog'),
		];
	}

	public function getTypeLabel(): string
	{
		return self::getTypeList()[$this->type] ?? \Yii::t('app', 'Unknown');
	}
}

