class FormatterHelper extends Component
{
	private Formatter $_formatter;

	public function __construct(Formatter $formatter, $config = [])
	{
		// Assign the injected formatter instance.
		$this->_formatter = $formatter;

		/**
		* Call to parent constructor
		* After setting custom properties, call the parent constructor.
		*
		* It is important to invoke the parent constructor at the end of this method
		* to ensure:
		* - Customize initialization before calling the parent constructor.
		* - The parent constructor should be called last to ensure proper object 
		*   initialization and handling of configuration settings.
		*/
		parent::__construct($config);
	}

	public function dateTime($datetime, $format = 'datetime')
	{
		return $this->_formatter->asDatetime($datetime, $format);
	}
}

