(function ($) {
	"use strict";

	var MQL = 992;/* Media query limit for when to apply scroll effects */
	var header = $('#header-navbar');
	var previousScroll = 0;/* Initialize the variable to track previous scroll position */
	header.addClass('is-fixed');/* Ensure the navbar starts fixed */
	if ($(window).width() > MQL) {

		$(window).on('scroll', debounce(function () {

			var currentScroll = $(this).scrollTop();
			var scrollHeight = $(document).height();
			var windowHeight = $(window).height();
			var distanceFromBottom = scrollHeight - (currentScroll + windowHeight);
			var threshold = 50;/* Set a threshold for how close to the bottom we need to be */
			if (currentScroll > previousScroll && distanceFromBottom > threshold) {

				header.removeClass('is-visible').addClass('is-hidden');
			}
			else if (currentScroll < previousScroll) {

				header.removeClass('is-hidden').addClass('is-visible');
			}

			previousScroll = currentScroll;
		}, 50));/* Debounce to improve performance */
	}

	/* Debounce function */
	function debounce(func, wait) {
		let timeout;
		return function () {
			const context = this;
			const args = arguments;
			clearTimeout(timeout);
			timeout = setTimeout(function () {
				func.apply(context, args);
			}, wait);
		};
	}
})(jQuery);

