<?php

namespace app\widgets\RandomizedForm;

use Yii;

/**
 * Core service that generates randomized field names,
 * stores them in session,
 * maps POST data back,
 * and checks honeypot fields.
 */
class Randomizer
{
    protected $sessionKey;

    protected $fieldMap = [];

    public function __construct($sessionKey = 'randomizedActiveFormFieldMap')
    {
        $this->sessionKey = $sessionKey;
    }

    /**
     * Generate random string identifiers for given field list
     * and store in session.
     */
    public function generate(array $fields)
    {
        $map = [];
        foreach ($fields as $field) {
            $map[$field] = $this->generateRandomString();
        }
        $this->fieldMap = $map;
        Yii::$app->session->set($this->sessionKey, $map);

        return $map;
    }

    /**
     * Retrieve the map from session or return empty array
     */
    public function getMap()
    {
        if (empty($this->fieldMap)) {
            $this->fieldMap = Yii::$app->session->get($this->sessionKey, []);
        }
        return $this->fieldMap;
    }

    /**
     * Reverse-map submitted POST data keys to logical attribute names.
     *
     * @param array $postData Raw POST data from request.
     * @return array mapped data in logical keys.
     */
    public function mapPostData(array $postData)
    {
        $map = $this->getMap();
        $reverseMap = array_flip($map);

        $mapped = [];
        foreach ($postData as $k => $v) {
            if (isset($reverseMap[$k])) {
                $mapped[$reverseMap[$k]] = $v;
