declare(strict_types=1);

namespace app\helpers;

use Throwable;

use Money\Money;
use Money\Currency;
use Money\Number;
use Money\Teller;
use Money\Currencies\ISOCurrencies;
use Money\Parser\IntlLocalizedDecimalParser;
use Money\Formatter\IntlMoneyFormatter;
use Money\Formatter\DecimalMoneyFormatter;

use Yii;
use yii ase\InvalidConfigException as YiiBaseInvalidConfigException;

use app\helpers\ExceptionLogger;
use app\helpers\FormatterHelper;
use app\helpers\LogHelper;

class MoneyHelper
{
	private static ?FormatterHelper $_formatter = null;

	private static function getFormatter(): FormatterHelper
	{
		if (self::$_formatter === null)
		{
			self::$_formatter = FormatterHelper::create(\Yii::$app->formatter);
		}

		return self::$_formatter;
	}

	private static function validateNumeric($value, string $context): void
	{
		if (!is_numeric($value))
		{
			$error = is_object($value) ? get_class($value) : gettype($value);
			$msg = \Yii::t('app', 'Money value has to be a numeric value in {context}, `{error}`', [
				'context' => $context,
				'error' => $error,
			]);

			\Yii::error($msg);

			throw new YiiBaseInvalidConfigException($msg);
		}
	}

	public static function getDiscount(string $price, string $discount): string
	{
		try
		{
			self::validateNumeric($price, 'getDiscount');
			self::validateNumeric($discount, 'getDiscount');

			$teller = Teller::USD();
			$discountAmount = $teller->multiply($price, $discount);

			return (string) $discountAmount;
		}
		catch (Throwable $e)
		{
			// Use the ExceptionLogger to handle and log the exception
			ExceptionLogger::log($e, 'money_helper_getDiscount_error_');

			return $e->getMessage();
		}	
	}

